package com.alsafa.native4;

import android.app.Activity;import android.graphics.Color;import android.os.Handler;import android.os.Looper;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.CheckBox;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.AdvancedSaleStore;import com.alsafa.native4.core.CoreProductCatalog;import com.alsafa.native4.core.CustomerCatalog;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.SplitPaymentStore;import java.util.ArrayList;import java.util.List;
/** Core sale bridge styled to match the familiar AlSafa sale flow, with independent amount/currency/account per payment leg. */
public final class CoreSalePanelBinder {
 private static final int INK=Color.rgb(62,52,41),MUTED=Color.rgb(138,123,108),PAPER=Color.rgb(255,253,249),SAND=Color.rgb(234,217,185),GOLD=Color.rgb(122,81,24);
 private final Activity a;private final Native4Services services;private final TextView status,selected,selectedCustomer;private final EditText search,qty,productId,customerSearch,customerId,discount,pointsUsed,tax,finalAmount,adjustmentReason,warranty,notes;private final Spinner currency,saleChannel;private final LinearLayout results,paymentRows,customerResults,saleItems;private final List<AdvancedSaleStore.SaleItem> basket=new ArrayList<>();private final CheckBox allowDue;private final CoreProductCatalog catalog;private final CustomerCatalog customers;private final Handler handler=new Handler(Looper.getMainLooper());private Runnable pending,customerPending;private String lastQuery="",lastCustomerQuery="";
 public CoreSalePanelBinder(Activity a,Native4Services services,TextView status){this.a=a;this.services=services;this.status=status;DeveloperDashboardPanelBinder.attach(a,services);bindDayRefresh(a);catalog=new CoreProductCatalog(services.db);customers=new CustomerCatalog(services.db);customerSearch=a.findViewById(R.id.saleCustomerSearch);customerId=a.findViewById(R.id.saleCustomerId);selectedCustomer=a.findViewById(R.id.saleSelectedCustomer);customerResults=a.findViewById(R.id.saleCustomerResults);search=a.findViewById(R.id.saleSearch);qty=a.findViewById(R.id.saleQuantity);currency=a.findViewById(R.id.saleCurrency);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));productId=a.findViewById(R.id.saleProductId);results=a.findViewById(R.id.saleSearchResults);selected=a.findViewById(R.id.saleSelectedProduct);paymentRows=a.findViewById(R.id.salePaymentRows);discount=a.findViewById(R.id.saleDiscount);pointsUsed=a.findViewById(R.id.salePointsUsed);tax=a.findViewById(R.id.saleTax);finalAmount=a.findViewById(R.id.saleFinalAmount);adjustmentReason=a.findViewById(R.id.saleAdjustmentReason);warranty=a.findViewById(R.id.saleWarranty);notes=a.findViewById(R.id.saleNotes);saleChannel=a.findViewById(R.id.saleChannel);saleChannel.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"🏪 بيع من المحل","🌐 بيع أونلاين"}));allowDue=a.findViewById(R.id.saleAllowDue);saleItems=a.findViewById(R.id.saleItems);styleSaleUi();a.findViewById(R.id.addSaleItem).setOnClickListener(v->addSelectedItem());a.findViewById(R.id.addManualSaleItem).setOnClickListener(v->addManualItem());a.findViewById(R.id.searchSaleProduct).setOnClickListener(v->searchNow(true));a.findViewById(R.id.addSalePayment).setOnClickListener(v->addPaymentRow(null));a.findViewById(R.id.saveSale).setOnClickListener(v->save());customerSearch.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){deferCustomerSearch();}public void afterTextChanged(android.text.Editable e){}});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){deferSearch();}public void afterTextChanged(android.text.Editable e){}});addPaymentRow(null);renderBasket();}
 private void styleSaleUi(){search.setHint("اسم الساعة أو الباركود");search.setTextSize(18);search.setTextColor(INK);search.setHintTextColor(MUTED);search.setBackgroundResource(R.drawable.alsafa_card);search.setPadding(dp(14),dp(12),dp(14),dp(12));qty.setHint("الكمية");qty.setTextSize(17);qty.setTextColor(INK);qty.setHintTextColor(MUTED);selected.setText("ابحث عن الساعة ثم اخترها من النتائج");selected.setTextColor(GOLD);selected.setTextSize(16);selected.setGravity(Gravity.END);selected.setPadding(dp(10),dp(12),dp(10),dp(12));Button searchButton=a.findViewById(R.id.searchSaleProduct);searchButton.setText("بحث عن الساعة");searchButton.setTextColor(INK);searchButton.setBackgroundResource(R.drawable.alsafa_card);Button add=a.findViewById(R.id.addSalePayment);add.setText("+ إضافة طريقة دفع أخرى");add.setTextColor(INK);add.setBackgroundResource(R.drawable.alsafa_card);Button save=a.findViewById(R.id.saveSale);save.setText("تثبيت المبيع");save.setTextSize(18);save.setTextColor(Color.WHITE);save.setMinHeight(dp(58));save.setBackgroundResource(R.drawable.alsafa_primary);}
 private static void bindDayRefresh(Activity a){int[] ids={R.id.openWorkDay,R.id.useLatestCarry,R.id.closeWorkDay};for(int id:ids){View v=a.findViewById(id);if(v!=null)v.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or_,ob)->DeveloperDashboardPanelBinder.refreshActive());}}
 private void addPaymentRow(String amount){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(10),dp(8),dp(10),dp(10));box.setBackgroundResource(R.drawable.alsafa_card);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);bp.setMargins(0,dp(6),0,dp(6));box.setLayoutParams(bp);TextView label=new TextView(a);label.setText("دفعة");label.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);label.setTextColor(INK);label.setGravity(Gravity.END);EditText value=new EditText(a);value.setHint("المبلغ المقبوض");value.setTextColor(INK);value.setHintTextColor(MUTED);value.setTextSize(17);value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);if(amount!=null)value.setText(amount);Spinner cur=new Spinner(a);cur.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));Spinner account=new Spinner(a);String[] accounts={"الدرج","شام كاش","الخزنة الخارجية","البنك"};account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,accounts));Button remove=new Button(a);remove.setText("حذف الدفعة");remove.setTextColor(MUTED);remove.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PAPER));remove.setOnClickListener(v->{if(paymentRows.getChildCount()>1)paymentRows.removeView(box);else value.setText("");});box.addView(label);box.addView(value);box.addView(cur);box.addView(account);box.addView(remove);box.setTag(new PaymentViews(value,cur,account));paymentRows.addView(box);}
 private List<SplitPaymentStore.Payment> readPayments(){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<paymentRows.getChildCount();i++){View row=paymentRows.getChildAt(i);PaymentViews p=(PaymentViews)row.getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;double amount=Double.parseDouble(raw);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,p.currency.getSelectedItemPosition());String account=accountCode(p.account.getSelectedItemPosition());String method="SHAM_CASH".equals(account)?"SHAM_CASH":"CASH";out.add(new SplitPaymentStore.Payment(amount,cur,method,account));}return out;}
 private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}
 private void deferCustomerSearch(){if(customerPending!=null)handler.removeCallbacks(customerPending);String q=customerSearch.getText().toString().trim();if(q.length()<2){lastCustomerQuery="";customerResults.removeAllViews();customerId.setText("");selectedCustomer.setText("بدون عميل محدد");return;}customerPending=()->searchCustomers();handler.postDelayed(customerPending,325);}
 private void searchCustomers(){try{String q=customerSearch.getText().toString().trim();if(q.equals(lastCustomerQuery))return;lastCustomerQuery=q;customerResults.removeAllViews();for(CustomerCatalog.Hit h:customers.search(q,20)){Button b=new Button(a);b.setAllCaps(false);b.setText(h.label());b.setGravity(Gravity.CENTER_VERTICAL|Gravity.END);b.setBackgroundResource(R.drawable.alsafa_card);b.setOnClickListener(v->{customerId.setText(h.id);selectedCustomer.setText("✓ "+h.label());lastCustomerQuery=h.name;customerSearch.setText(h.name);customerSearch.setSelection(customerSearch.length());customerResults.removeAllViews();});customerResults.addView(b);}}catch(Exception e){status.setText("تعذر بحث العميل: "+msg(e));}}
 private void deferSearch(){if(pending!=null)handler.removeCallbacks(pending);String q=search.getText().toString().trim();if(q.length()<2){lastQuery="";results.removeAllViews();return;}pending=()->searchNow(false);handler.postDelayed(pending,325);}
 private void searchNow(boolean force){try{String q=search.getText().toString().trim();if(!force&&q.equals(lastQuery))return;lastQuery=q;results.removeAllViews();List<CoreProductCatalog.ProductHit> hits=catalog.search(q,20);for(CoreProductCatalog.ProductHit h:hits){Button b=new Button(a);b.setAllCaps(false);b.setText(h.label());b.setGravity(Gravity.CENTER_VERTICAL|Gravity.END);b.setMinHeight(dp(64));b.setTextSize(17);b.setTextColor(INK);b.setBackgroundResource(R.drawable.alsafa_card);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,dp(3),0,dp(3));b.setLayoutParams(lp);b.setOnClickListener(v->select(h));results.addView(b);}if(hits.isEmpty()){TextView t=new TextView(a);t.setText("لا توجد ساعة مطابقة");t.setTextColor(MUTED);t.setGravity(Gravity.END);t.setPadding(dp(12),dp(14),dp(12),dp(14));results.addView(t);}}catch(Exception e){status.setText("تعذر البحث: "+msg(e));}}
 private void select(CoreProductCatalog.ProductHit h){if(pending!=null)handler.removeCallbacks(pending);productId.setText(h.id);selected.setText("✓ "+h.label());lastQuery=h.name;search.setText(h.name);search.setSelection(search.length());results.removeAllViews();status.setText("تم اختيار الساعة — أكمل الكمية والدفع");}
 private void addSelectedItem(){try{String id=productId.getText().toString().trim();if(id.isEmpty())throw new IllegalArgumentException("اختر الساعة أولاً");int q=Integer.parseInt(qty.getText().toString().trim());if(q<=0)throw new IllegalArgumentException("الكمية غير صالحة");basket.add(new AdvancedSaleStore.SaleItem(id,q));renderBasket();basket.clear();renderBasket();qty.setText("");productId.setText("");selected.setText("ابحث عن الساعة ثم اخترها من النتائج");search.setText("");results.removeAllViews();lastQuery="";}catch(Exception e){status.setText("تعذر إضافة الصنف: "+msg(e));}}
 private void addManualItem(){final EditText name=new EditText(a);name.setHint("اسم الصنف اليدوي");final EditText q=new EditText(a);q.setHint("الكمية");q.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);final EditText price=new EditText(a);price.setHint("سعر الوحدة");price.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),0,dp(12),0);box.addView(name);box.addView(q);box.addView(price);new android.app.AlertDialog.Builder(a).setTitle("إضافة صنف يدوي").setView(box).setNegativeButton("إلغاء",null).setPositiveButton("إضافة",(d,w)->{try{int n=Integer.parseInt(q.getText().toString().trim());double p=Double.parseDouble(price.getText().toString().trim());basket.add(new AdvancedSaleStore.SaleItem("",name.getText().toString(),n,p));renderBasket();}catch(Exception e){status.setText("بيانات الصنف اليدوي غير صالحة");}}).show();}
 private void renderBasket(){saleItems.removeAllViews();for(int i=0;i<basket.size();i++){final int ix=i;AdvancedSaleStore.SaleItem x=basket.get(i);LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);Button del=new Button(a);del.setText("حذف");del.setOnClickListener(v->{basket.remove(ix);renderBasket();});TextView t=new TextView(a);t.setText((x.description.isEmpty()?"ساعة مختارة":x.description)+" × "+x.quantity);t.setGravity(Gravity.END);t.setTextColor(INK);t.setPadding(dp(8),dp(8),dp(8),dp(8));row.addView(del,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT));row.addView(t,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));saleItems.addView(row);}if(basket.isEmpty()){TextView t=new TextView(a);t.setText("لم تتم إضافة أصناف بعد");t.setGravity(Gravity.END);t.setTextColor(MUTED);saleItems.addView(t);}}
 private void save(){try{if(basket.isEmpty()){String id=productId.getText().toString().trim();if(!id.isEmpty()){int q=Integer.parseInt(qty.getText().toString().trim());basket.add(new AdvancedSaleStore.SaleItem(id,q));}else throw new IllegalArgumentException("أضف صنفاً واحداً على الأقل");}String invoiceCur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition());double disc=optionalDouble(discount);int pts=optionalInt(pointsUsed);String cid=customerId.getText().toString().trim();if(pts>0&&cid.isEmpty())throw new IllegalArgumentException("اختر العميل أولاً لاستخدام النقاط");List<SplitPaymentStore.Payment> payments=readPayments();if(payments.isEmpty()&&!allowDue.isChecked())throw new IllegalArgumentException("أدخل دفعة واحدة على الأقل أو فعّل البيع الآجل");Double negotiated=optionalNullableDouble(finalAmount);double taxValue=optionalDouble(tax);String reason=adjustmentReason.getText().toString().trim();if(negotiated!=null&&!reason.isEmpty()){confirmAndSave(invoiceCur,cid,disc,pts,payments,negotiated,taxValue,reason);return;}if(negotiated!=null)throw new IllegalArgumentException("اكتب سبب تعديل السعر النهائي");AdvancedSaleStore.Result r=saveDetailed(invoiceCur,cid,disc,pts,payments,null,taxValue,false,"");Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();status.setText("✓ تمت الفاتورة "+r.invoiceNo+" — "+fmt(r.total)+" "+invoiceCur+" — "+payments.size()+" دفعة");qty.setText("");productId.setText("");selected.setText("ابحث عن الساعة ثم اخترها من النتائج");lastQuery="";search.setText("");results.removeAllViews();customerId.setText("");customerSearch.setText("");selectedCustomer.setText("بدون عميل محدد");customerResults.removeAllViews();lastCustomerQuery="";discount.setText("");pointsUsed.setText("");paymentRows.removeAllViews();allowDue.setChecked(false);addPaymentRow(null);}catch(Exception e){status.setText("لم تُنفذ الفاتورة: "+msg(e));}}
 private AdvancedSaleStore.Result saveDetailed(String invoiceCur,String cid,double disc,int pts,List<SplitPaymentStore.Payment> payments,Double negotiated,double taxValue,boolean confirmed,String reason)throws Exception{String channel=saleChannel.getSelectedItemPosition()==1?"ONLINE":"STORE";String payStatus=payments.isEmpty()?"DUE":(allowDue.isChecked()?"PARTIAL":"PAID");return services.sales.saleItemsDetailed(basket,cid,disc,invoiceCur,payments,pts,allowDue.isChecked(),negotiated,confirmed,reason,channel,payStatus,taxValue,warranty.getText().toString(),notes.getText().toString(),System.currentTimeMillis());}
 private void confirmAndSave(String invoiceCur,String cid,double disc,int pts,List<SplitPaymentStore.Payment> payments,double negotiated,double taxValue,String reason){new android.app.AlertDialog.Builder(a).setTitle("تأكيد السعر النهائي").setMessage("سيتم تسجيل تعديل السعر وسببه ضمن الفاتورة. هل تريد المتابعة؟").setNegativeButton("إلغاء",null).setPositiveButton("تأكيد",(d,w)->{try{AdvancedSaleStore.Result r=saveDetailed(invoiceCur,cid,disc,pts,payments,negotiated,taxValue,true,reason);afterSaved(r,invoiceCur,payments.size());}catch(Exception e){status.setText("لم تُنفذ الفاتورة: "+msg(e));}}).show();}
 private void afterSaved(AdvancedSaleStore.Result r,String invoiceCur,int paymentCount){Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();status.setText("✓ تمت الفاتورة "+r.invoiceNo+" — "+fmt(r.total)+" "+invoiceCur+" — "+paymentCount+" دفعة");basket.clear();renderBasket();qty.setText("");productId.setText("");selected.setText("ابحث عن الساعة ثم اخترها من النتائج");lastQuery="";search.setText("");results.removeAllViews();customerId.setText("");customerSearch.setText("");selectedCustomer.setText("بدون عميل محدد");customerResults.removeAllViews();lastCustomerQuery="";discount.setText("");pointsUsed.setText("");tax.setText("");finalAmount.setText("");adjustmentReason.setText("");warranty.setText("");notes.setText("");paymentRows.removeAllViews();allowDue.setChecked(false);saleChannel.setSelection(0);addPaymentRow(null);}
 private static Double optionalNullableDouble(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?null:Double.parseDouble(s);}private static double optionalDouble(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private static int optionalInt(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Integer.parseInt(s);}
 private static final class PaymentViews{final EditText amount;final Spinner currency,account;PaymentViews(EditText a,Spinner c,Spinner ac){amount=a;currency=c;account=ac;}}
 private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
